custom.propContract:
interface Annotation {
  x: number
  y: number
  text: string
  position?: "top" | "bottom" | "left" | "right"
}

interface AnnotatedImageProps {
  imageSrc?: string
  imageAlt?: string
  annotations: Annotation[]
  timing?: Timing
  beats?: Beat[]
}

interface BarChartItem {
  label: string
  value: number
  color?: string
}

interface BarChartProps {
  title?: string
  items: BarChartItem[]
  highlightIndex?: number
  showValues?: boolean
  timing?: Timing
  beats?: Beat[]
}

interface Metric {
  value: string
  label: string
  prefix?: string
  suffix?: string
}

interface BigNumberProps {
  title?: string
  metrics: Metric[]
  timing?: Timing
  beats?: Beat[]
}

interface BlockDiagramBlock {
  label: string
  detail: string
}

interface BlockDiagramProps {
  title?: string
  blocks: BlockDiagramBlock[]
  timing?: Timing
  beats?: Beat[]
}

interface ContentBlock {
  type: "header" | "card-row" | "text" | "placeholder" | "button"
  text?: string
}

interface BrowserMockupProps {
  url: string
  title?: string
  variant?: "light" | "dark"
  content: ContentBlock[]
  timing?: Timing
  beats?: Beat[]
}

interface ClapperboardProps {
  mode?: "action" | "cut"
  title?: string
  subtitle?: string
  configLines?: string[]
}

interface CodeBlockProps {
  code: string
  language: string
  title?: string
  highlightLines?: number[]
  timing?: Timing
  beats?: Beat[]
}

type TokenType = "key" | "value" | "comment" | "string" | "punctuation" | "heading" | "default"

interface Token {
  text: string
  type: TokenType
}

interface CodeDiffProps {
  fileName: string
  additions: string[]
  deletions: string[]
  context?: { before?: string[]; after?: string[] }
  title?: string
  timing?: Timing
  beats?: Beat[]
}

interface CreditEntry {
  role: string
  name: string
}

interface CrewCreditsProps {
  title?: string
  credits?: CreditEntry[]
  producedBy?: string
  footer?: string
}

interface EtalonProps {
  title?: string
  captions?: string[]
  timing?: Timing
  beats?: Beat[]
}

interface Geometry {
  d: string
  totalLength: number
  entryLength: number
  firstHit: [number, number]
  exits: Array<{ point: [number, number]; length: number }>
}

interface ProgressBarItem {
  label: string
  value: number
  color?: string
}

interface ProgressBarsProps {
  title?: string
  items: ProgressBarItem[]
  timing?: Timing
  beats?: Beat[]
}

interface PanelConfig {
  label: string
  icon?: "check" | "cross" | "folder" | "user" | "code"
  items: string[]
  accent?: string
}

interface SplitScreenProps {
  title?: string
  left?: PanelConfig
  right?: PanelConfig
  timing?: Timing
  beats?: Beat[]
}

interface TimelineItem {
  date: string
  text: string
  status?: "past" | "current" | "future"
}

interface TimelineProps {
  title?: string
  items: TimelineItem[]
  timing?: Timing
  beats?: Beat[]
}

interface LogoItem {
  src?: string
  label?: string
}

interface LogoWallProps {
  title?: string
  items: LogoItem[]
  columns?: 3 | 4 | 6
  timing?: Timing
  beats?: Beat[]
}

interface ColumnContent {
  title: string
  body: string
}

interface TwoColumnTextProps {
  title?: string
  left: ColumnContent
  right: ColumnContent
  timing?: Timing
  beats?: Beat[]
}

interface Step {
  title: string
  description?: string
  status?: "completed" | "current" | "pending"
}

interface StepListProps {
  title?: string
  steps: Step[]
  timing?: Timing
  beats?: Beat[]
}
